<!-- interior-gallery -->
<section class="interior-gallery">
    <div class="container">
        <div class="interior-gallery__content">
            <div class="head-content fade-in-up">
                <h2 class="title title--h2">Пространства, которые&nbsp;мы&nbsp;создаём</h2>
                <div class="subtitle"><p>Когда архитектор и&nbsp;дизайнер работают в&nbsp;связке с&nbsp;первого дня, результат получается цельным и&nbsp;продуманным до&nbsp;мелочей.</p></div>
            </div>
            <div class="interior-gallery__grid">
                <div class="interior-gallery__item fade-in">
                    <picture>
                        <source srcset="img/default.png" data-srcset="img/interior-gallery/1.webp 1x, img/interior-gallery/1@2x.webp 2x" type="image/webp">
                        <source srcset="img/default.png" data-srcset="img/interior-gallery/1.jpg 1x, img/interior-gallery/1@2x.jpg 2x" type="image/jpeg">
                        <img class="lazyload" src="img/default.png" data-srcset="img/interior-gallery/1.jpg 1x, img/interior-gallery/1@2x.jpg 2x" alt="img">
                    </picture>
                </div>
                <div class="interior-gallery__item fade-in">
                    <picture>
                        <source srcset="img/default.png" data-srcset="img/interior-gallery/2.webp 1x, img/interior-gallery/2@2x.webp 2x" type="image/webp">
                        <source srcset="img/default.png" data-srcset="img/interior-gallery/2.jpg 1x, img/interior-gallery/2@2x.jpg 2x" type="image/jpeg">
                        <img class="lazyload" src="img/default.png" data-srcset="img/interior-gallery/2.jpg 1x, img/interior-gallery/2@2x.jpg 2x" alt="img">
                    </picture>
                </div>
                <div class="interior-gallery__item fade-in interior-gallery__item--3">
                    <picture>
                        <source srcset="img/default.png" data-srcset="img/interior-gallery/3.webp 1x, img/interior-gallery/3@2x.webp 2x" type="image/webp">
                        <source srcset="img/default.png" data-srcset="img/interior-gallery/3.jpg 1x, img/interior-gallery/3@2x.jpg 2x" type="image/jpeg">
                        <img class="lazyload" src="img/default.png" data-srcset="img/interior-gallery/3.jpg 1x, img/interior-gallery/3@2x.jpg 2x" alt="img">
                    </picture>
                </div>
            </div>
        </div>
    </div>
</section>